import { CRAFT_DISCIPLINE_ENUM } from "../../constants.mjs";

/**
 * Shared "blueprint" block — crafting data embedded directly in the product item
 * (see CRAFT_IMPLEMENTATION_PLAN.md §2.1). Spread into defineSchema() of all
 * "physical" item types next to physicalItemFields().
 *
 * Item type `recipe` (a character's "recipe knowledge") is a thin reference to the product
 * and is GENERATED by a macro from this data; the ingredient list is never duplicated by hand.
 *
 * cost_price isn't edited by hand: it is baked by the price
 * recalculation (button on the sheet / the economy recalculation macro), formula:
 *   cost_price  = Σ(ingredient base_price × amount)
 *   base_price  = cost_price × (1 + markup_pct/100)
 *
 * @returns {object} Field object to spread into defineSchema().
 */
export function craftingFields() {
  const { SchemaField, StringField, NumberField, BooleanField, ArrayField } = foundry.data.fields;
  return {
    crafting: new SchemaField({
      // Whether the item is crafted at all (gate for generating recipes and prices)
      craftable: new BooleanField({ required: true, initial: false }),
      // Functional craft discipline (empty = not set)
      discipline: new StringField({ required: true, blank: true, initial: "", choices: ["", ...CRAFT_DISCIPLINE_ENUM] }),
      // Ingredients: the uuid is stored as the compendium one, name is a human-readable fallback
      // (UUIDs change when an item is moved onto an actor, see plan §3.3)
      ingredients: new ArrayField(new SchemaField({
        uuid: new StringField({ required: true, blank: true, initial: "" }),
        name: new StringField({ required: true, blank: true, initial: "" }),
        amount: new NumberField({ required: true, nullable: false, initial: 1, min: 0 })
      })),
      // Markup in % over the cost price
      markup_pct: new NumberField({ required: true, nullable: false, initial: 50, min: 0 }),
      // Cost price — baked by the recalculation, not edited by hand
      cost_price: new NumberField({ required: true, nullable: false, initial: 0, min: 0 }),
      // How many units of the product one crafting cycle yields (3 vials of a potion, etc.)
      output_quantity: new NumberField({ required: true, nullable: false, integer: true, initial: 1, min: 1 }),
      // Explicit time in hours; 0 = standard time by rarity (table 1.1)
      time_override: new NumberField({ required: true, nullable: false, initial: 0, min: 0 })
    })
  };
}

/**
 * Migration of legacy data in the crafting block. Call from static migrateData(source)
 * of EVERY model that spreads craftingFields(): the discipline's choices validation
 * runs before data preparation, and an outdated value breaks initialization
 * of the whole item (Failed to initialize Item).
 */
export function migrateCraftingData(source) {
  // The "Weaving" discipline was renamed to "Tailoring" (2026-07-16): weaving → tailoring.
  if (source.crafting?.discipline === "weaving") source.crafting.discipline = "tailoring";
}
